<?php
if (!isset($db) || empty($_SESSION['user_id'])) { http_response_code(404); exit; }
$editing=one('SELECT * FROM customers WHERE id=?',[(int)($_GET['edit']??0)]);
$posted=($_POST['action']??'')==='customer';
$search=trim(substr((string)($_GET['q']??''),0,190));
$sort=isset(CUSTOMER_SORTS[$_GET['sort']??'']) ? $_GET['sort'] : 'name';
$total=customers_count($search); $all=$search==='' ? $total : customers_count('');
$pages=max(1,(int)ceil($total/CUSTOMERS_PER_PAGE));
$pageNo=min($pages,max(1,(int)($_GET['p']??1)));
$customers=customers_list($search,$sort,CUSTOMERS_PER_PAGE,($pageNo-1)*CUSTOMERS_PER_PAGE);
// Keeps the current search and sort in page and download links.
$link=fn(array $change)=>'index.php?'.http_build_query(array_filter(array_merge(['page'=>'customers','q'=>$search,'sort'=>$sort==='name'?null:$sort],$change),fn($v)=>$v!==null && $v!==''));
$first=$total ? ($pageNo-1)*CUSTOMERS_PER_PAGE+1 : 0; $last=min($total,$pageNo*CUSTOMERS_PER_PAGE);
// Only the administrator can delete. Customers with documents need a second, explicit warning.
$canDelete=is_admin() && $total>0;
if ($canDelete) { [$cw,$cp]=customers_filter($search); $allRisk=customers_risk($cw,$cp); }
$risk=fn(array $c)=>(int)$c['quotations']+(int)$c['invoices'] ? $c['name'].': '.((int)$c['quotations']+(int)$c['invoices']).' document'.((int)$c['quotations']+(int)$c['invoices']===1?'':'s').((int)$c['paid_total']?' with '.$config['currency'].' '.money((int)$c['paid_total']).' paid':'') : '';
?>
<div class="toolbar"><p class="muted">You have <strong><?=e($all)?></strong> customer<?=$all===1?'':'s'?> in the system.</p><div class="actions"><?php if ($all): ?><a class="button quiet" href="<?=e($link(['export'=>'csv','p'=>null]))?>">Download list (CSV)</a><?php endif ?><a class="button" href="index.php?page=import">Import Excel / CSV</a></div></div>
<details class="card customer-form" id="customer-form"<?=($editing || $posted || !$all)?' open':''?>><summary><h2><?=$editing?'Edit customer: '.e($editing['name']):'+ Add a customer'?></h2></summary>
<form method="post"><?=csrf()?><input type="hidden" name="action" value="customer"><input type="hidden" name="id" value="<?=e($editing['id']??($_POST['id']??0))?>"><div class="form-grid"><?php foreach (['name'=>'Customer / company name','email'=>'Email','phone'=>'Phone'] as $key=>$label): ?><label><?=$label?><input name="<?=$key?>" type="<?=$key==='email'?'email':'text'?>" value="<?=e($_POST[$key]??$editing[$key]??'')?>" maxlength="<?=$key==='phone'?80:190?>" <?=$key==='name'?'required':''?>></label><?php endforeach ?></div><label>Address / service location<textarea name="address" maxlength="2000"><?=e($_POST['address']??$editing['address']??'')?></textarea></label><button>Save customer</button><?php if ($editing): ?> <a href="index.php?page=customers">Cancel</a><?php endif ?></form></details>
<section class="card"><div class="section-head"><h2>All customers</h2>
<form method="get" class="inline customer-search"><input type="hidden" name="page" value="customers"><input aria-label="Search customers" name="q" value="<?=e($search)?>" placeholder="Search name, email, phone or address"><label>Sort<select name="sort"><?php foreach (CUSTOMER_SORTS as $key=>$label): ?><option value="<?=$key?>" <?=$sort===$key?'selected':''?>><?=e($label)?></option><?php endforeach ?></select></label><button>Show</button><?php if ($search!==''): ?><a href="index.php?page=customers">Clear</a><?php endif ?></form></div>
<p class="muted"><?php if ($total): ?>Showing <?=$first?>–<?=$last?> of <?=$total?><?=$search!==''?' matching "'.e($search).'"':''?>.<?php endif ?></p>
<?php if ($canDelete): ?><form method="post" class="bulk-form" data-plural="customers"><?=csrf()?><input type="hidden" name="action" value="customers_delete"><input type="hidden" name="q" value="<?=e($search)?>"><input type="hidden" name="confirmed" value=""><div class="bulk-bar" hidden><strong class="bulk-count">0 selected</strong><button type="button" class="quiet bulk-mark">Mark all on this page</button><button type="submit" class="danger">Delete selected</button><button type="submit" name="all" value="1" class="quiet danger-text" data-what="all <?=$total?> customer<?=$total===1?'':'s'?><?=$search!==''?' matching &quot;'.e($search).'&quot;':''?>" data-risk="<?=e($allRisk)?>">Delete all <?=$total?></button><button type="button" class="link-button bulk-clear">Clear</button></div><?php endif ?>
<div class="table-wrap"><table><thead><tr><?php if ($canDelete): ?><th class="pick"><input type="checkbox" class="pick-all" aria-label="Tick every customer on this page"></th><?php endif ?><th>Customer</th><th>Contact</th><th>Added</th><th>Documents</th><th class="num">Outstanding · <?=e($config['currency'])?></th><th></th></tr></thead><tbody>
<?php foreach ($customers as $c): $used=(int)$c['quotations']+(int)$c['invoices']>0; ?><tr><?php if ($canDelete): ?><td class="pick"><input type="checkbox" name="ids[]" value="<?=$c['id']?>" class="pick-one" aria-label="Tick <?=e($c['name'])?>" data-label="<?=e($c['name'])?>" data-risk="<?=e($risk($c))?>"></td><?php endif ?><td><a href="index.php?page=customer&id=<?=$c['id']?>"><strong><?=e($c['name'])?></strong></a><small><?=e($c['address'])?></small></td><td><?=e($c['email'])?><small><?=e($c['phone'])?></small></td><td class="nowrap"><?=e(substr((string)$c['created_at'],0,10))?></td><td class="nowrap"><?=(int)$c['quotations']?> proforma<?=(int)$c['quotations']===1?'':'s'?><small><?=(int)$c['invoices']?> tax invoice<?=(int)$c['invoices']===1?'':'s'?></small></td><td class="num"><?php if ((int)$c['outstanding']>0): ?><strong><?=money((int)$c['outstanding'])?></strong><?php else: ?><span class="muted">—</span><?php endif ?></td><td class="nowrap"><a href="index.php?page=customer&id=<?=$c['id']?>">View</a> · <a href="index.php?page=customers&edit=<?=$c['id']?>#customer-form">Edit</a><?php if ($canDelete): ?> · <button type="submit" name="only" value="<?=$c['id']?>" class="link-button danger-text" data-label="<?=e($c['name'])?>" data-risk="<?=e($risk($c))?>">Delete</button><?php endif ?></td></tr><?php endforeach ?>
<?php if (!$customers): ?><tr><td colspan="<?=$canDelete?7:6?>"><?=$search!==''?'No customers match your search.':'No customers yet. Add your first customer above or import a spreadsheet.'?></td></tr><?php endif ?></tbody></table></div><?php if ($canDelete): ?></form><?php endif ?>
<?php if ($pages>1): ?><nav class="pager" aria-label="Customer pages"><?php if ($pageNo>1): ?><a href="<?=e($link(['p'=>$pageNo-1]))?>">← Previous</a><?php endif ?><span>Page <?=$pageNo?> of <?=$pages?></span><?php if ($pageNo<$pages): ?><a href="<?=e($link(['p'=>$pageNo+1]))?>">Next →</a><?php endif ?></nav><?php endif ?>
</section>
